"""Concurrent progress I/O fixture; generated bytes only, no model imports."""
import os
import json
from pathlib import Path
import sys
import time
import issue27frontend_transfer_control_v2 as control

s=control.s


def main():
    mode,out=sys.argv[1],Path(sys.argv[2])
    base=(s.ROOT/'tmp/task_knowledge_transfer_synthetic_v2').resolve()
    s.require(base in out.resolve().parents,'FIXTURE_DIRECTORY_ONLY')
    if mode=='supervise':
        command=[str(s.PYTHON),'-B',str(Path(__file__).resolve()),'worker',str(out)]
        result=control.v1.supervise('T',out,dict(seconds=45,memory=2*1024**3,output=8*1024**2),command,synthetic=True)
        print(json.dumps(result,ensure_ascii=True));return
    deadline=time.monotonic()+30
    while not (out/'worker_gate.json').exists():
        s.require(time.monotonic()<deadline,'GATE_TIMEOUT');time.sleep(.01)
    gate=s.read_json(out/'worker_gate.json')
    s.require(gate['pid']==os.getpid() and gate['parent_pid']==os.getppid(),'GATE')
    for i in range(500):
        s.atomic_json(out/'progress.json',dict(phase='GENERATED_IO_STRESS',updates=i,padding='x'*4096))
        time.sleep(.002)
    (out/'generated.txt').write_text('500 completed progress replacements',encoding='utf-8')
    s.atomic_json(out/'worker_terminal.json',dict(status='WORK_COMPLETE_VERIFIED',stage='T',recipe_sha256=s.RECIPE_SHA,
        output_hashes={'generated.txt':s.sha(out/'generated.txt')}))


if __name__=='__main__':
    main()
